<script setup>
import { computed, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ArrowLeftRight, CalendarCheck2, CalendarDays, CalendarPlus, CheckCircle2, Clock3 } from '@lucide/vue'
import { useAppStore } from '../stores/app'
import Dialog from '../features/admin/AdminDialog.vue'
import { dateLabel, fullName, initials, timeLabel } from '../features/timebank/format'
import { useClock } from '../features/timebank/use-clock'
const store = useAppStore(), route = useRoute(), router = useRouter()
const now = useClock()
const tab = ref('solicitudes'), direction = ref('recibidas'), status = ref(''), action = ref(null), reason = ref(''), error = ref('')
watch(() => route.query.tab, (value) => { tab.value = value === 'reservas' ? 'reservas' : 'solicitudes'; status.value = '' }, { immediate: true })
const requests = computed(() => store.myRequests.filter((row) => (direction.value === 'recibidas' ? row.id_ofertante === store.user.id : row.id_solicitante === store.user.id) && (!status.value || row.estado === status.value)))
const reservations = computed(() => store.myReservations.filter((row) => !status.value || row.estado === status.value))
const other = (row) => store.findUser(row.id_ofertante === store.user.id ? row.id_solicitante : row.id_ofertante)
const ownConfirmation = (row) => row.id_solicitante === store.user.id ? row.confirmacion_solicitante_at : row.confirmacion_ofertante_at
const otherConfirmation = (row) => row.id_solicitante === store.user.id ? row.confirmacion_ofertante_at : row.confirmacion_solicitante_at
const actionTitles = { accept: 'Aceptar solicitud', reject: 'Rechazar solicitud', 'cancel-request': 'Cancelar solicitud', 'cancel-reservation': 'Cancelar reserva', confirm: 'Confirmar servicio terminado' }
async function addToCalendar(row) {
  try {
    const { authorizationUrl } = await store.addReservationToGoogleCalendar(row.id_reserva)
    if (!authorizationUrl) throw new Error('No se recibió la autorización de Google.')
    window.location.assign(authorizationUrl)
  } catch (failure) {
    store.showToast(failure.message || 'No se pudo conectar con Google Calendar.', 'error')
  }
}
function setTab(value) { router.replace({ name: 'exchanges', query: value === 'reservas' ? { tab: value } : {} }) }
function openAction(kind, row) {
  if (!store.requireSession()) return
  action.value = { kind, row }; reason.value = ''; error.value = ''
}
async function submitAction() {
  const { kind, row } = action.value
  try {
    if (kind === 'cancel-reservation') await store.cancelReservation(row.id_reserva, reason.value)
    else if (kind === 'confirm') await store.confirmReservation(row.id_reserva)
    else await store.respondRequest(row.id_solicitud, kind === 'cancel-request' ? 'cancel' : kind)
    action.value = null
    store.showToast(kind === 'accept' ? 'Solicitud aceptada. La reserva ya aparece en Reservas.' : kind === 'confirm' ? 'Confirmación registrada.' : 'Cambio registrado.')
  } catch (failure) { error.value = failure.message }
}
</script>
<template>
  <header class="workspace-header"><div><h1>Mis intercambios</h1><p>De una solicitud a un momento para aprender juntos.</p></div><RouterLink class="button button-outline" to="/">Explorar habilidades</RouterLink></header>
  <div class="workspace-tabs" role="group" aria-label="Sección de intercambios"><button type="button" data-dialog-return-focus :aria-pressed="tab === 'solicitudes'" :class="{active: tab === 'solicitudes'}" @click="setTab('solicitudes')"><ArrowLeftRight :size="18" />Solicitudes<span>{{ store.myRequests.length }}</span></button><button type="button" :aria-pressed="tab === 'reservas'" :class="{active: tab === 'reservas'}" @click="setTab('reservas')"><CalendarCheck2 :size="18" />Reservas<span>{{ store.myReservations.length }}</span></button></div>
  <div class="exchange-toolbar"><div v-if="tab === 'solicitudes'" class="segmented" role="group" aria-label="Dirección de solicitudes"><button type="button" :class="{active: direction === 'recibidas'}" :aria-pressed="direction === 'recibidas'" @click="direction = 'recibidas'">Recibidas</button><button type="button" :class="{active: direction === 'enviadas'}" :aria-pressed="direction === 'enviadas'" @click="direction = 'enviadas'">Enviadas</button></div><p v-else class="subtle-label">Horario de La Paz. Las reservas se crean al aceptar una solicitud.</p><label class="select-wrap"><span class="sr-only">Filtrar por estado</span><select v-model="status"><option value="">Todos los estados</option><option v-for="value in tab === 'solicitudes' ? ['Solicitada','Aceptada','Rechazada','Cancelada'] : ['Confirmada','Completada','Cancelada']" :key="value" :value="value">{{ value }}</option></select></label></div>
  <section v-if="tab === 'solicitudes'" class="exchange-list" aria-label="Listado de solicitudes"><article v-for="row in requests" :key="row.id_solicitud" class="exchange-record"><div class="exchange-person"><span class="avatar">{{ initials(other(row)) }}</span><div><strong>{{ fullName(other(row)) }}</strong><small>{{ direction === 'recibidas' ? 'Quiere aprender contigo' : 'Tu solicitud para aprender' }}</small></div><span class="state-label" :class="{'state-muted': row.estado !== 'Solicitada'}">{{ row.estado }}</span></div><h2>{{ store.findSkill(row.id_habilidad)?.nombre }}</h2><p v-if="row.descripcion" class="exchange-description">{{ row.descripcion }}</p><div class="record-details"><span><CalendarDays :size="17" />{{ dateLabel(row.fecha_inicio_propuesta) }}</span><span><Clock3 :size="17" />{{ timeLabel(row.fecha_inicio_propuesta) }}–{{ timeLabel(row.fecha_fin_propuesta) }}</span><strong>{{ row.creditos_requeridos }} créditos</strong></div><footer v-if="row.estado === 'Solicitada'" class="record-actions"><template v-if="direction === 'recibidas'"><button class="button button-outline" type="button" @click="openAction('reject', row)">Rechazar</button><button class="button button-primary" type="button" @click="openAction('accept', row)">Aceptar solicitud</button></template><button v-else class="button button-outline" type="button" @click="openAction('cancel-request', row)">Cancelar solicitud</button></footer><RouterLink v-else-if="row.estado === 'Aceptada'" class="text-link" to="/intercambios?tab=reservas">Ver reservas</RouterLink></article><div v-if="!requests.length" class="panel empty-state"><ArrowLeftRight :size="28" /><h2>No hay solicitudes {{ direction }}</h2><p>{{ status ? 'Prueba con otro estado.' : 'Las solicitudes de intercambio aparecerán aquí.' }}</p><button v-if="status" class="button button-outline" type="button" @click="status = ''">Mostrar todos los estados</button></div></section>
  <section v-else class="exchange-list" aria-label="Listado de reservas"><article v-for="row in reservations" :key="row.id_reserva" class="exchange-record"><div class="exchange-person"><span class="avatar">{{ initials(other(row)) }}</span><div><strong>{{ fullName(other(row)) }}</strong><small>{{ row.id_ofertante === store.user.id ? 'Compartes tu habilidad' : 'Aprendes una habilidad' }}</small></div><span class="state-label" :class="{'state-muted': row.estado === 'Cancelada'}">{{ row.estado }}</span></div><h2>{{ store.findSkill(row.id_habilidad)?.nombre }}</h2><div class="record-details"><span><CalendarDays :size="17" />{{ dateLabel(row.fecha_inicio) }}</span><span><Clock3 :size="17" />{{ timeLabel(row.fecha_inicio) }}–{{ timeLabel(row.fecha_fin) }}</span><strong>{{ row.creditos }} créditos</strong></div><template v-if="row.estado === 'Confirmada'"><div class="reservation-confirmations"><span :class="{done: ownConfirmation(row)}"><CheckCircle2 :size="17" />{{ ownConfirmation(row) ? 'Ya confirmaste' : 'Falta tu confirmación' }}</span><span :class="{done: otherConfirmation(row)}"><CheckCircle2 :size="17" />{{ otherConfirmation(row) ? 'La otra persona confirmó' : 'Falta la otra confirmación' }}</span></div><footer class="record-actions"><button class="button button-outline record-calendar" type="button" @click="addToCalendar(row)"><CalendarPlus :size="18" />Agregar a Google Calendar</button><button class="button button-outline" type="button" :disabled="now >= Date.parse(row.fecha_inicio)" :title="now >= Date.parse(row.fecha_inicio) ? 'Después del inicio debes contactar a administración.' : undefined" @click="openAction('cancel-reservation', row)">Cancelar reserva</button><button class="button button-primary" type="button" :disabled="now < Date.parse(row.fecha_fin) || !!ownConfirmation(row)" @click="openAction('confirm', row)">{{ ownConfirmation(row) ? 'Confirmación enviada' : 'Confirmar servicio' }}</button></footer><p class="field-hint">{{ now < Date.parse(row.fecha_fin) ? 'Podrás confirmar cuando termine el horario reservado.' : 'Los créditos se transfieren cuando ambos participantes confirman.' }}</p></template><p v-else-if="row.motivo_cancelacion" class="field-hint">Motivo: {{ row.motivo_cancelacion }}</p><p v-else-if="row.estado === 'Completada'" class="field-hint">Ambas personas confirmaron. La transferencia de créditos está completada.</p></article><div v-if="!reservations.length" class="panel empty-state"><CalendarCheck2 :size="28" /><h2>No hay reservas para mostrar</h2><p>Al aceptar una solicitud, el horario reservado aparecerá aquí.</p><button v-if="status" class="button button-outline" type="button" @click="status = ''">Mostrar todos los estados</button></div></section>
  <Dialog :open="!!action" labelledby="exchange-action-title" describedby="exchange-action-description" @close="action = null"><template v-if="action"><h2 id="exchange-action-title">{{ actionTitles[action.kind] }}</h2><p id="exchange-action-description" class="lead-copy">{{ store.findSkill(action.row.id_habilidad)?.nombre }} con {{ fullName(other(action.row)) }}.</p><p v-if="action.kind === 'accept'" class="notice">Se creará una reserva y se retendrán {{ action.row.creditos_requeridos }} créditos de quien solicita el intercambio.</p><p v-else-if="action.kind === 'confirm'" class="notice">Confirma que el intercambio se realizó. Los créditos se transferirán una sola vez, cuando ambos hayan confirmado.</p><p v-else-if="action.kind === 'cancel-reservation'" class="notice">La reserva se cancelará y se liberarán los créditos retenidos.</p><p v-else class="notice">La solicitud dejará de estar pendiente. No se modificarán créditos.</p><form class="flow-form" @submit.prevent="submitAction"><div v-if="action.kind === 'cancel-reservation'" class="field"><label for="reservation-reason">Motivo de cancelación</label><textarea id="reservation-reason" v-model="reason" maxlength="500" rows="3" required></textarea></div><p v-if="error" class="notice notice-error" role="alert">{{ error }}</p><footer class="admin-dialog-actions"><button class="button button-outline" type="button" data-autofocus @click="action = null">Volver</button><button class="button button-primary" type="submit">{{ actionTitles[action.kind] }}</button></footer></form></template></Dialog>
</template>
